import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"Install ComfyUI","description":"Install ComfyUI with LAN listen for MiniTavern image gen using the built-in default workflow.","frontmatter":{"title":"Install ComfyUI","description":"Install ComfyUI with LAN listen for MiniTavern image gen using the built-in default workflow.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Install ComfyUI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Install ComfyUI with LAN listen for MiniTavern image gen using the built-in default workflow."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local/image-gen/comfyui"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local/image-gen/comfyui"}]]},"headers":[],"relativePath":"en/local/image-gen/comfyui.md","filePath":"en/local/image-gen/comfyui.md","lastUpdated":1787224147000}'),n={name:"en/local/image-gen/comfyui.md"};function o(l,e,r,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="install-comfyui" tabindex="-1">Install ComfyUI <a class="header-anchor" href="#install-comfyui" aria-label="Permalink to &quot;Install ComfyUI&quot;">​</a></h1><p>ComfyUI is a node-based local image front-end with fast new-model support.<br> MiniTavern submits a <strong>built-in default workflow</strong> via ComfyUI’s HTTP API (<code>/prompt</code>, etc.); you do not need to draw a node graph in the App to generate images.</p><p>Official docs: <a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">docs.comfy.org</a> · repo: <a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">Comfy-Org/ComfyUI</a></p><h2 id="hardware-tips" tabindex="-1">Hardware tips <a class="header-anchor" href="#hardware-tips" aria-label="Permalink to &quot;Hardware tips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>VRAM</th><th>Suggestion</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5 and smaller workflows</td></tr><tr><td>8–12GB</td><td>SDXL and some fast Flux variants more realistic</td></tr><tr><td>Apple Silicon</td><td>Native run; usually slower than similar NVIDIA</td></tr></tbody></table><h2 id="option-a-windows-portable-recommended" tabindex="-1">Option A: Windows portable (recommended) <a class="header-anchor" href="#option-a-windows-portable-recommended" aria-label="Permalink to &quot;Option A: Windows portable (recommended)&quot;">​</a></h2><ol><li>Open <a href="https://www.comfy.org/download" target="_blank" rel="noreferrer">ComfyUI downloads</a> (or a community <code>ComfyUI_windows_portable</code> pack).</li><li>Extract to a non-system path (short path; avoid Chinese spaces if possible).</li><li>With NVIDIA run <code>run_nvidia_gpu.bat</code>; CPU-only use the matching CPU script.</li><li>Open the address shown in the browser, often:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><h2 id="option-b-desktop-app" tabindex="-1">Option B: Desktop app <a class="header-anchor" href="#option-b-desktop-app" aria-label="Permalink to &quot;Option B: Desktop app&quot;">​</a></h2><ol><li>Install <a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">ComfyUI Desktop</a>.</li><li>Settings → Server Configuration (or similar “server / network”): <ul><li>Set <strong>Listen Address</strong> to <code>0.0.0.0</code> (default <code>127.0.0.1</code> blocks the phone)</li><li>Note <strong>Port</strong> (Desktop often <strong>8000</strong>, unlike portable 8188)</li></ul></li><li>Restart, then access via LAN IP.</li></ol><h2 id="option-c-manual-git-macos-linux-advanced" tabindex="-1">Option C: Manual Git (macOS / Linux / advanced) <a class="header-anchor" href="#option-c-manual-git-macos-linux-advanced" aria-label="Permalink to &quot;Option C: Manual Git (macOS / Linux / advanced)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Comfy-Org/ComfyUI.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ComfyUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: venv\\Scripts\\activate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install matching PyTorch for your GPU (see PyTorch site)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span></span></code></pre></div><h2 id="enable-lan-required-for-phone" tabindex="-1">Enable LAN (required for phone) <a class="header-anchor" href="#enable-lan-required-for-phone" aria-label="Permalink to &quot;Enable LAN (required for phone)&quot;">​</a></h2><h3 id="portable-cli" tabindex="-1">Portable / CLI <a class="header-anchor" href="#portable-cli" aria-label="Permalink to &quot;Portable / CLI&quot;">​</a></h3><p>Edit the launch script (e.g. <code>run_nvidia_gpu.bat</code>) and add after <code>main.py</code>:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--listen</span></span></code></pre></div><p>Full example:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\python_embeded\\python.exe -s ComfyUI\\main.py --windows-standalone-build --listen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Role</th></tr></thead><tbody><tr><td><code>--listen</code></td><td>With no args, listen on all interfaces for LAN</td></tr><tr><td><code>--port 8188</code></td><td>Optional port change</td></tr><tr><td><code>--enable-cors-header</code></td><td>For browser CORS; phone App → API usually does not need it</td></tr></tbody></table><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>As above: Listen <code>0.0.0.0</code>, port per UI.</p><h2 id="place-models" tabindex="-1">Place models <a class="header-anchor" href="#place-models" aria-label="Permalink to &quot;Place models&quot;">​</a></h2><p>Put checkpoints (<code>.safetensors</code>) in:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComfyUI/models/checkpoints/</span></span></code></pre></div><p>Press <code>R</code> in the UI to refresh, or restart. Confirm a default text-to-image run in the ComfyUI web UI before connecting the App.</p><p>Sources: <a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> · <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a>.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>On PC:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><p>LAN (PC IP; watch Desktop port):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:8188</span></span></code></pre></div><p>If the phone browser opens the same address, network and listen are OK.</p><h2 id="differences-vs-minitavern-read-first" tabindex="-1">Differences vs MiniTavern (read first) <a class="header-anchor" href="#differences-vs-minitavern-read-first" aria-label="Permalink to &quot;Differences vs MiniTavern (read first)&quot;">​</a></h2><ul><li>The App uses a <strong>built-in default workflow</strong> and generally picks an available checkpoint on your machine; complex custom graphs are out of scope here.</li><li>Current default Comfy flow <strong>does not use reference images</strong> (having refs does not error); for face lock use <a href="./a1111">A1111</a> or a cloud platform with refs.</li><li>Sleep / lid close stops the service; IP changes require updating Base URL in the App.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./connect-app">Configure in MiniTavern</a></li><li>Overview: <a href="./index">Image model deploy</a></li></ul>`,36)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
